row_rules.PR_ORDER:
if app_rules_pr.bypass = 0 then  -- rows written by the APP_ACT_PR buttons: legacy values kept
if inserting then
  -- PR_ORDER PRE-INSERT / WHEN-CREATE-RECORD / TRNS_TYPE_CODE and SUPPLIER_CODE WVI
  if nvl(:new.confirm_flag, 0) = 1 then
    raise_application_error(-20142, 'لا يمكن إنشاء أمر شراء معتمد: يجب حفظ الأمر وأصنافه أولاً ثم الاعتماد');
  end if;
  :new.confirm_flag := 0;
  :new.close_flag := nvl(:new.close_flag, 0);
  :new.st_srv_asst_flag := nvl(:new.st_srv_asst_flag, 1);
  :new.doc_no := nvl(:new.doc_no, app_rules_pr.next_order_doc_no);
  :new.store_code := nvl(:new.store_code, app_rules_pr.type_store(:new.trns_type_code));
  if :new.supplier_code is not null and nvl(:new.currency_code, 1) = 1 and app_rules_pr.supplier_currency(:new.supplier_code) <> 1 then
    :new.currency_code := app_rules_pr.supplier_currency(:new.supplier_code);
    :new.currency_rate := app_rules_pr.currency_rate(:new.currency_code, :new.pr_order_date, 1);
  end if;
else
  -- CHECK_CLOSE: a confirmed or closed order is read-only (only CONFIRM_FLAG / CLOSE_FLAG may change)
  if (nvl(:old.confirm_flag, 0) = 1 or nvl(:old.close_flag, 0) = 1)
     and app_rules_pr.chg(:new.pr_order_date, :old.pr_order_date)
       + app_rules_pr.chg(:new.doc_no, :old.doc_no)
       + app_rules_pr.chg(:new.supplier_code, :old.supplier_code)
       + app_rules_pr.chg(:new.cntrct_serial, :old.cntrct_serial)
       + app_rules_pr.chg(:new.store_code, :old.store_code)
       + app_rules_pr.chg(:new.requisition_type, :old.requisition_type)
       + app_rules_pr.chg(:new.currency_code, :old.currency_code)
       + app_rules_pr.chg(:new.currency_rate, :old.currency_rate)
       + app_rules_pr.chg(:new.payment_method, :old.payment_method)
       + app_rules_pr.chg(:new.payment_condition_code, :old.payment_condition_code)
       + app_rules_pr.chg(:new.term_ship_code, :old.term_ship_code)
       + app_rules_pr.chg(:new.notes, :old.notes)
       + app_rules_pr.chg(:new.disc_val, :old.disc_val)
       + app_rules_pr.chg(:new.tot_disc1_ratio, :old.tot_disc1_ratio)
       + app_rules_pr.chg(:new.tot_disc2_ratio, :old.tot_disc2_ratio)
       + app_rules_pr.chg(:new.tot_disc3_ratio, :old.tot_disc3_ratio)
       + app_rules_pr.chg(:new.tot_disc1_value, :old.tot_disc1_value)
       + app_rules_pr.chg(:new.tot_disc2_value, :old.tot_disc2_value)
       + app_rules_pr.chg(:new.tot_disc3_value, :old.tot_disc3_value)
       + app_rules_pr.chg(:new.shipment_type, :old.shipment_type)
       + app_rules_pr.chg(:new.fotter1_memo, :old.fotter1_memo)
       + app_rules_pr.chg(:new.fotter2_memo, :old.fotter2_memo)
       + app_rules_pr.chg(:new.fotter3_memo, :old.fotter3_memo)
       + app_rules_pr.chg(:new.fotter4_memo, :old.fotter4_memo)
       + app_rules_pr.chg(:new.fotter5_memo, :old.fotter5_memo)
       + app_rules_pr.chg(:new.bonus_with_vat, :old.bonus_with_vat)
       + app_rules_pr.chg(:new.tax_value2, :old.tax_value2)
       + app_rules_pr.chg(:new.tax_value1, :old.tax_value1) > 0 then
    raise_application_error(-20131, 'أمر الشراء معتمد أو مقفل ولا يمكن تعديله - يجب إلغاء الاعتماد أو الإقفال أولاً');
  end if;
  app_rules_pr.order_update_check(:new.trns_type_code, :new.trns_serial, :old.confirm_flag, :new.confirm_flag);
end if;
end if;

row_rules.PR_ORDER_DET:
if app_rules_pr.bypass = 0 then  -- rows written by the APP_ACT_PR buttons: legacy values kept
-- PR_ORDER_DET PRE-INSERT / WVI: confirmed or closed orders are read-only, price and quantity mandatory
app_rules_pr.order_line_guard(:new.trns_type_code, :new.trns_serial);
if :new.item_code is not null then
  :new.group_code := nvl(:new.group_code, app_rules_pr.item_group(:new.item_code));
  :new.unit_code := nvl(:new.unit_code, app_rules_pr.basic_unit(:new.group_code, :new.item_code));
end if;
:new.pr_order_date := nvl(:new.pr_order_date, app_rules_pr.order_date(:new.trns_type_code, :new.trns_serial));
if (inserting or app_rules_pr.chg(:new.vn_price, :old.vn_price) = 1) and nvl(:new.vn_price, 0) = 0 then
  raise_application_error(-20141, 'لابد من ادخال سعر الوحدة - الصنف ' || :new.item_code);
end if;
if (inserting or app_rules_pr.chg(:new.quantity, :old.quantity) + app_rules_pr.chg(:new.bonus, :old.bonus)
                 + app_rules_pr.chg(:new.extra_bonus, :old.extra_bonus) > 0)
   and (nvl(:new.quantity, 0) < 0 or nvl(:new.bonus, 0) < 0
        or nvl(:new.quantity, 0) + nvl(:new.bonus, 0) + nvl(:new.extra_bonus, 0) <= 0
        or nvl(:new.quantity, 0) + nvl(:new.bonus, 0) + nvl(:new.extra_bonus, 0) > 999999999999) then
  raise_application_error(-20141, 'الكمية لا بد أن تكون أكبر من الصفر و اقل من 999999999999 - الصنف ' || :new.item_code);
end if;
app_rules_pr.pair_ratio(inserting, :new.quantity, :old.quantity, :new.percentage, :old.percentage, :new.bonus, :old.bonus);
app_rules_pr.pair_ratio(inserting, :new.quantity, :old.quantity, :new.extra_percentage, :old.extra_percentage, :new.extra_bonus, :old.extra_bonus);
app_rules_pr.disc_chain(inserting, :new.vn_price, :old.vn_price,
                        :new.disc1_ratio, :old.disc1_ratio, :new.disc1_value, :old.disc1_value,
                        :new.disc2_ratio, :old.disc2_ratio, :new.disc2_value, :old.disc2_value,
                        :new.disc3_ratio, :old.disc3_ratio, :new.disc3_value, :old.disc3_value);
end if;

row_rules.PR_ORDER_SRVC:
if app_rules_pr.bypass = 0 then  -- rows written by the APP_ACT_PR buttons: legacy values kept
-- PR_ORDER_SRVC: read-only when the order is confirmed / closed; COST_PRCN between 0 and 100
app_rules_pr.order_line_guard(:new.trns_type_code, :new.trns_serial);
if nvl(:new.cost_prcn, 0) not between 0 and 100 then
  raise_application_error(-20141, 'النسبة غير صحيحة');
end if;
:new.pr_order_date := nvl(:new.pr_order_date, app_rules_pr.order_date(:new.trns_type_code, :new.trns_serial));
end if;

row_rules.PR_ORDER_ASST:
if app_rules_pr.bypass = 0 then  -- rows written by the APP_ACT_PR buttons: legacy values kept
-- PR_ORDER_ASST: read-only when the order is confirmed / closed
app_rules_pr.order_line_guard(:new.trns_type_code, :new.trns_serial);
:new.pr_order_date := nvl(:new.pr_order_date, app_rules_pr.order_date(:new.trns_type_code, :new.trns_serial));
end if;
